    "settings.webhooksTitle": "Webhooks",
    "settings.webhooksBody": "サイト全体の webhook（サーバー全体の停止とセキュリティイベント）は管理セクションの「サイト全体の Webhook」ページに、各自の webhook はそれぞれの Webhooks ページにあります。以前ここで通知 URL を設定していた場合は、サイト全体の webhook としてそちらへ移しました。",
